                                                                                                                                                                                          'yeşil '
                                                                                                                                                                                          'noktalar '
                                                                                                                                                                                          'ulaşabildiği '
                                                                                                                                                                                          'hücrelerdir. '
                                                                                                                                                                                          'Sağ altta '
                                                                                                                                                                                          'ek işareti '
                                                                                                                                                                                          'olan taşlar '
                                                                                                                                                                                          'bileşiktir.',
